class Account:
    def __init__(self, owner):
        self.owner = owner
        self._balance = 0

    @property
    def balance(self):
        return self._balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self._balance += amount

acct = Account("Ana")
acct.deposit(25)
print(acct.balance)
try:
    acct.balance = 1000
except AttributeError:
    print("balance is read-only")

