class Account:
    def __init__(self, owner):
        self.owner = owner
        self._balance = 0

    @property
    def balance(self):
        return self._balance

    def deposit(self, amount):
        self._balance += amount

tests.code:
try:
    Account('Ben').__setattr__('balance', 99)
except AttributeError:
    pass
else:
    raise AssertionError('balance should be read-only (a property with no setter).')

