class Thermostat:
    def __init__(self, target):
        self.target = target

    @property
    def target(self):
        return self._target

    @target.setter
    def target(self, value):
        if not 10 <= value <= 30:
            raise ValueError("target must be between 10 and 30")
        self._target = value

tests.code:
try:
    Thermostat(20).__setattr__('target', 35)
except ValueError:
    pass
else:
    raise AssertionError('Targets above 30 should raise ValueError.')

try:
    Thermostat(5)
except ValueError:
    pass
else:
    raise AssertionError('The starting target should be validated too.')

