import hashlib

class Password:
    def __init__(self, text):
        self._hash = self._digest(text)

    @staticmethod
    def _digest(text):
        return hashlib.sha256(text.encode()).hexdigest()

    def check(self, text):
        return self._digest(text) == self._hash

