class Inventory:
    def __init__(self):
        self._items = {}

    def add(self, name, qty):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._items[name] = self._items.get(name, 0) + qty

    def remove(self, name, qty):
        if self._items.get(name, 0) < qty:
            raise ValueError("not enough stock")
        self._items[name] -= qty

    @property
    def items(self):
        return dict(self._items)

tests.code:
try:
    Inventory().remove('x', 1)
except ValueError:
    pass
else:
    raise AssertionError('Removing missing stock should raise ValueError.')
try:
    Inventory().add('x', 0)
except ValueError:
    pass
else:
    raise AssertionError('Adding 0 should raise ValueError.')
